#ifdef GL_ES
precision mediump float;
#endif


// Number of wave lines
const int NUM_LINES = 40;

// Thickness of each line
const float LINE_THICKNESS = 0.01;

// How strong the audio affects the lines
const float AUDIO_SCALE = 0.3;

// Vertical spread of lines: they go from y=-0.7 to y=+0.7
const float MIN_Y = -1.1;
const float MAX_Y =  0.9;

// Frequency of the base sine wave that each line has
// (we’ll vary phase by line index as well)
const float BASE_FREQ = 9.0;  

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //----------------------------------------------------
    // 1) Normalize pixel coords to [-1,+1], correct aspect
    //----------------------------------------------------
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;  // preserve aspect ratio

    //----------------------------------------------------
    // 2) Accumulate brightness from all wave lines
    //----------------------------------------------------
    float colorAccum = 0.0;

    for(int j = 0; j < NUM_LINES; j++)
    {
        // Fraction fi in [0..1] for line j
        float fi = float(j) / float(NUM_LINES - 1);

        //----------------------------------------------
        // 2a) Baseline: line j is at y_baseline
        //----------------------------------------------
        float y_baseline = mix(MIN_Y, MAX_Y, fi);

        //----------------------------------------------
        // 2b) Sample FFT for this line’s frequency bin
        //     (In Shadertoy FFT textures, x=0..1 is freq)
        //----------------------------------------------
        float fftVal = texture(iChannel0, vec2(fi, 0.0)).r;  
        // shape it a bit
        fftVal = pow(fftVal, 1.2);

        //----------------------------------------------
        // 2c) Define the “wave function” y_j(x):
        //     y_j(x) = y_baseline
        //              + sin( x * BASE_FREQ + iTime + j*phaseOffset )
        //              + (fftVal * AUDIO_SCALE)
        //----------------------------------------------
        // Let’s define a small phase offset so each line’s wave is slightly shifted
        float phaseOffset =0.5*sin((3.14159*float(iFrame))/300.0) * float(j);

        // Our wave function (for the current line j)
        float yj_of_x = y_baseline
                      + 0.08 * sin((uv.x + iTime) * BASE_FREQ + phaseOffset)
                      + fftVal * AUDIO_SCALE;

        //----------------------------------------------
        // 2d) Distance from the pixel’s y to that line
        //----------------------------------------------
        float distToLine = abs(uv.y - yj_of_x);

        //----------------------------------------------
        // 2e) Convert distance to a “thin line” brightness
        //----------------------------------------------
        // If distToLine < LINE_THICKNESS, lineVal ~ 1
        // if distToLine > LINE_THICKNESS, lineVal ~ 0
        float lineVal = smoothstep(0.0, LINE_THICKNESS, LINE_THICKNESS - distToLine);

        // Add it to the accumulator
        colorAccum += lineVal;
    }

    //----------------------------------------------------
    // 3) Final color
    //----------------------------------------------------
    // White lines on black background
    vec3 color = vec3(colorAccum);

    // (Optional) Slight contrast/gamma shaping
    color = 1.0 - exp(-color * 3.5);

    // (Optional) pick RGB[0,1] value for color2 to color the lines
    vec3 color2 = vec3(.4,.7,.5);
    color -= vec3((1.0-color2.x), (1.0-color2.y), (1.0-color2.z));  

    fragColor = vec4(color, 1.0);
}
